package com.fixmer.genesis.technology.workspace.live122;
import com.fixmer.genesis.technology.workspace.collaboration121.*;import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;import java.util.zip.*;
/** Bounded canonical transport. No authorization identity is accepted in request fields. */
public final class WorkspaceCodec122 {
 public static final int REQUEST=32700,RESPONSE=512000,MAX_NODES=32768,MAX_FIELDS=48;
 private WorkspaceCodec122(){}
 public static byte[] encode(Map<String,String> fields,int max)throws IOException{if(fields.isEmpty()||fields.size()>MAX_FIELDS)throw new IOException("FORMAT");var bytes=new ByteArrayOutputStream();try(var o=new DataOutputStream(bytes)){o.writeInt(fields.size());for(var e:new TreeMap<>(fields).entrySet()){if(!e.getKey().matches("[A-Za-z][A-Za-z0-9]{0,31}"))throw new IOException("FORMAT");o.writeUTF(e.getKey());if(e.getValue().length()>max)throw new IOException("LIMIT");ByteBuffer encoded=StandardCharsets.UTF_8.newEncoder().onMalformedInput(CodingErrorAction.REPORT).encode(CharBuffer.wrap(e.getValue()));byte[] b=new byte[encoded.remaining()];encoded.get(b);if(b.length>max)throw new IOException("LIMIT");o.writeInt(b.length);o.write(b);}}if(bytes.size()>max)throw new IOException("LIMIT");return bytes.toByteArray();}
 public static Map<String,String> decode(byte[] bytes,int max)throws IOException{if(bytes.length>max)throw new IOException("LIMIT");try(var i=new DataInputStream(new ByteArrayInputStream(bytes))){int n=count(i,MAX_FIELDS);if(n==0)throw new IOException("FORMAT");var out=new TreeMap<String,String>();for(int k=0;k<n;k++){String key=i.readUTF();int len=count(i,max);byte[] b=i.readNBytes(len);if(b.length!=len)throw new EOFException();String value=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();if(out.put(key,value)!=null)throw new IOException("FORMAT");}if(i.available()!=0||!Arrays.equals(bytes,encode(out,max)))throw new IOException("FORMAT");return Map.copyOf(out);}}
 public static void id(DataOutputStream o,CollaborativeDocument121.Id id)throws IOException{o.writeLong(id.actor().getMostSignificantBits());o.writeLong(id.actor().getLeastSignificantBits());o.writeLong(id.clock());}
 public static CollaborativeDocument121.Id id(DataInputStream i)throws IOException{return new CollaborativeDocument121.Id(new UUID(i.readLong(),i.readLong()),i.readLong());}
 public static String id(CollaborativeDocument121.Id id){return id.actor()+":"+id.clock();}public static CollaborativeDocument121.Id id(String value){int n=value.lastIndexOf(':');if(n<1)throw new IllegalArgumentException("ANCHOR");return new CollaborativeDocument121.Id(UUID.fromString(value.substring(0,n)),Long.parseLong(value.substring(n+1)));}
 public static String batch(CollaborativeDocument121.Batch batch)throws IOException{var bytes=new ByteArrayOutputStream();try(var o=new DataOutputStream(bytes)){o.writeInt(batch.inserts().size());for(var n:batch.inserts()){id(o,n.id());id(o,n.after());o.writeInt(n.codepoint());}o.writeInt(batch.deletes().size());for(var id:batch.deletes())id(o,id);}if(bytes.size()>20000)throw new IOException("LIMIT");return Base64.getEncoder().encodeToString(bytes.toByteArray());}
 public static CollaborativeDocument121.Batch batch(UUID actor,String value)throws IOException{try(var i=new DataInputStream(new ByteArrayInputStream(unbase(value,20000)))){int n=count(i,256);var inserts=new ArrayList<CollaborativeDocument121.Insert>();for(int k=0;k<n;k++)inserts.add(new CollaborativeDocument121.Insert(id(i),id(i),i.readInt()));int nd=count(i,256);var deletes=new ArrayList<CollaborativeDocument121.Id>();for(int k=0;k<nd;k++)deletes.add(id(i));if(i.available()!=0)throw new IOException("FORMAT");return new CollaborativeDocument121.Batch(actor,inserts,deletes);}catch(IllegalArgumentException e){throw new IOException("FORMAT",e);}}
 public static String document(CollaborativeDocument121.Snapshot doc)throws IOException{if(doc.nodes().size()>MAX_NODES)throw new IOException("DOCUMENT_LIMIT");var bytes=new ByteArrayOutputStream();try(var o=new DataOutputStream(new DeflaterOutputStream(bytes))){o.writeLong(doc.revision());o.writeInt(doc.nodes().size());for(var n:doc.nodes()){id(o,n.id());id(o,n.after());o.writeInt(n.codepoint());o.writeBoolean(doc.deleted().contains(n.id()));}}if(bytes.size()>280000)throw new IOException("DOCUMENT_LIMIT");return Base64.getEncoder().encodeToString(bytes.toByteArray());}
 public static CollaborativeDocument121.Snapshot document(String value)throws IOException{byte[] bytes=inflate142(unbase(value,280000),MAX_NODES*53+12,"DOCUMENT_LIMIT");try(var i=new DataInputStream(new ByteArrayInputStream(bytes))){long rev=i.readLong();int n=count(i,MAX_NODES);var nodes=new ArrayList<CollaborativeDocument121.Insert>();var deleted=new HashSet<CollaborativeDocument121.Id>();for(int k=0;k<n;k++){var node=new CollaborativeDocument121.Insert(id(i),id(i),i.readInt());nodes.add(node);if(i.readBoolean())deleted.add(node.id());}if(i.available()!=0)throw new IOException("FORMAT");var d=new CollaborativeDocument121.Snapshot(nodes,deleted,rev);new CollaborativeDocument121(d);return d;}catch(IllegalArgumentException e){throw new IOException("FORMAT",e);}}
 /** One bounded zlib stream, without ignored padding or concatenated extra streams. */
 static byte[] inflate142(byte[] packed,int limit,String limitCode)throws IOException {
  Inflater inflater=new Inflater();
  try(var input=new ByteArrayInputStream(packed);var stream=new InflaterInputStream(input,inflater)){
   byte[] raw=stream.readNBytes(limit+1);
   if(raw.length>limit)throw new IOException(limitCode);
   if(!inflater.finished()||inflater.getRemaining()!=0||input.available()!=0)throw new IOException("FORMAT");
   return raw;
  }finally{inflater.end();}
 }
 private static int count(DataInputStream i,int max)throws IOException{int n=i.readInt();if(n<0||n>max)throw new IOException("LIMIT");return n;}
 private static byte[] unbase(String s,int max)throws IOException{if(s.length()>(max+2)/3*4)throw new IOException("LIMIT");try{byte[] b=Base64.getDecoder().decode(s);if(b.length>max||!Base64.getEncoder().encodeToString(b).equals(s))throw new IOException("FORMAT");return b;}catch(IllegalArgumentException e){throw new IOException("FORMAT",e);}}
}
